  "Pro is bought in the Google Play version of Attune — one tap, paid by card or from your Vodafone / Orange / Etisalat balance, and it switches on by itself.": "Pro، Attune کے Google Play ورژن میں خریدا جاتا ہے — ایک ٹیپ، ادائیگی کارڈ سے یا اپنے Vodafone / Orange / Etisalat بیلنس سے، اور یہ خود ہی آن ہو جاتا ہے۔",
  "Cancel any time in Google Play → Subscriptions. The plan renews by itself; nothing to send, nobody to message.": "Google Play ← سبسکرپشنز میں کسی بھی وقت منسوخ کریں۔ پلان خود ہی رینیو ہوتا ہے؛ نہ کچھ بھیجنا، نہ کسی کو میسج کرنا۔",
