  "a year ago": "ایک سال پہلے",
  "from your past": "آپ کے ماضی سے",
  "Nothing to read in that.": "اس میں پڑھنے کو کچھ نہیں۔",
  "That payment did not go through, so there is nothing to record.": "وہ ادائیگی مکمل نہیں ہوئی، اس لیے درج کرنے کو کچھ نہیں۔",
  "Sent to Yusr — pick the account and confirm": "Yusr کو بھیج دیا — اکاؤنٹ چنیں اور تصدیق کریں",
  "Money isn't bundled in this build.": "اس بلڈ میں پیسوں کا حصہ شامل نہیں۔",
  "The Yusr document wasn't embedded. On the phone it loads from local assets.": "Yusr دستاویز شامل نہیں کی گئی۔ فون پر یہ ایپ کی اپنی فائلوں سے لوڈ ہوتی ہے۔",
  "Your ledger and every zakāt ruling live here, unchanged, and free forever. Attune adds memory and plain language on top — it never calculates zakāt and never moves money on its own.": "آپ کا کھاتہ اور زکوٰۃ کا ہر حکم یہاں ہے، بغیر تبدیلی کے، اور ہمیشہ مفت۔ Attune اوپر سے یادداشت اور آسان زبان شامل کرتا ہے — یہ کبھی زکوٰۃ کا حساب نہیں لگاتا اور کبھی خود سے پیسے منتقل نہیں کرتا۔",
  "Share a payment": "ادائیگی شیئر کریں",
  "An InstaPay confirmation, a bank SMS, a wallet receipt or a photo of one. Attune reads the amount and who it was, then opens your own transaction sheet with it filled in. You pick the account.": "InstaPay کی تصدیق، بینک کا SMS، والٹ کی رسید یا ان میں سے کسی کی تصویر۔ Attune رقم اور فریق پڑھ لیتا ہے، پھر آپ کی ٹرانزیکشن شیٹ اسی سے بھر کر کھولتا ہے۔ اکاؤنٹ آپ چنتے ہیں۔",
  "تم تحويل مبلغ 1,500.00 جنيه إلى AHMED MOHAMED. رقم العملية 987654321": "EGP 1,500.00 کی رقم AHMED MOHAMED کو منتقل کر دی گئی۔ ٹرانزیکشن نمبر 987654321",
  "Read it": "پڑھیں",
  "Reading…": "پڑھا جا رہا ہے…",
  "From a photo": "تصویر سے",
  "Three ways, all fine: share the SMS, WhatsApp message or screenshot to Attune from any app (it lands here by itself) · paste it above · or take/pick a photo of the receipt.": "تین طریقے، سب ٹھیک: کسی بھی ایپ سے SMS، WhatsApp میسج یا اسکرین شاٹ Attune کو شیئر کریں (یہ خود یہاں آ جاتا ہے) · اوپر پیسٹ کریں · یا رسید کی تصویر لیں یا چنیں۔",
  "read from: “": "یہاں سے پڑھا: “",
  "· account: you choose, in Yusr": "· اکاؤنٹ: آپ Yusr میں چنتے ہیں",
  "Talk to your money": "اپنے پیسوں سے بات کریں",
  "not saved to memory": "یادداشت میں محفوظ نہیں",
  "saved to memory": "یادداشت میں محفوظ",
  "Answered on this device from the figures Yusr calculated. Ask follow-ups — it keeps the thread. For zakāt it is handed the app's own numbers and forbidden from recomputing them: it explains, it does not rule.": "اسی ڈیوائس پر Yusr کے نکالے گئے اعداد سے جواب دیا گیا۔ مزید سوال پوچھیں — یہ بات کا سلسلہ یاد رکھتا ہے۔ زکوٰۃ کے لیے اسے ایپ کے اپنے اعداد دیے جاتے ہیں اور دوبارہ حساب لگانا منع ہے: یہ سمجھاتا ہے، فتویٰ نہیں دیتا۔",
  "figures from Yusr's zakāt engine, not recalculated": "Yusr کے زکوٰۃ انجن کے اعداد، دوبارہ حساب کے بغیر",
