  "What do you make of this?": "اس بارے میں کیا خیال ہے؟",
  "Load a model in Engine and this answers with no signal.": "انجن میں ماڈل لوڈ کریں، پھر یہ بغیر سگنل کے بھی جواب دے گا۔",
  "What stands out": "نمایاں باتیں",
  "Every figure here is one Yusr calculated — the model may not produce a new number.": "یہاں ہر عدد Yusr نے نکالا ہے — ماڈل کوئی نیا عدد نہیں بنا سکتا۔",
  "What the AI is allowed to see": "AI کیا دیکھ سکتا ہے",
