  "Added to memory": "یادداشت میں شامل",
  "Only what you confirmed. Attune records nothing on its own.": "صرف وہی جس کی آپ نے تصدیق کی۔ Attune خود سے کچھ درج نہیں کرتا۔",
  "No signal, so only your saved places are searchable — nothing matched.": "سگنل نہیں، اس لیے صرف آپ کی محفوظ جگہیں تلاش ہو سکتی ہیں — کچھ نہیں ملا۔",
  "Nothing found for that.": "اس کے لیے کچھ نہیں ملا۔",
  "Saved — it works offline now": "محفوظ — اب یہ آف لائن بھی چلتا ہے",
  "Map tiles cleared": "نقشے کے محفوظ حصے صاف ہو گئے",
  "Every area you look at is kept, so it works again with no signal. You can also download an area before you travel. Place search needs a connection; your own saved places are searchable without one.": "جو بھی علاقہ آپ دیکھتے ہیں وہ محفوظ ہو جاتا ہے، تاکہ بغیر سگنل کے دوبارہ چلے۔ آپ سفر سے پہلے کوئی علاقہ ڈاؤن لوڈ بھی کر سکتے ہیں۔ جگہ کی تلاش کے لیے انٹرنیٹ چاہیے؛ اپنی محفوظ جگہیں آپ اس کے بغیر بھی تلاش کر سکتے ہیں۔",
  "offline — showing saved tiles": "آف لائن — محفوظ نقشہ دکھایا جا رہا ہے",
  "Search a place — مدينة نصر، القاهرة": "جگہ تلاش کریں — مدينة نصر، القاهرة",
  "Search your saved places": "اپنی محفوظ جگہوں میں تلاش کریں",
  "· saved": "· محفوظ",
  "not downloaded": "ڈاؤن لوڈ نہیں ہوا",
  "Translate…": "ترجمہ کریں…",
  "Translating into {l} — part {n} of {t}…": "{l} میں ترجمہ ہو رہا ہے — حصہ {n} از {t}…",
  "{n} piece(s) couldn't be translated and were left as they were.": "{n} حصوں کا ترجمہ نہیں ہو سکا، انہیں ویسے ہی چھوڑ دیا گیا۔",
  "Translated by the AI on your phone — check important names and numbers.": "آپ کے فون پر AI نے ترجمہ کیا — اہم نام اور نمبر چیک کر لیں۔",
  "Translating needs an AI model — open Engine and install one.": "ترجمے کے لیے AI ماڈل چاہیے — انجن کھولیں اور ایک انسٹال کریں۔",
  "The AI on your phone translates it piece by piece; headings, lists, tables and numbers stay in place. Long files take a few minutes.": "آپ کے فون پر AI اسے حصہ حصہ ترجمہ کرتا ہے؛ عنوانات، فہرستیں، ٹیبلز اور نمبر اپنی جگہ رہتے ہیں۔ لمبی فائلوں میں چند منٹ لگتے ہیں۔",
  "Unlimited video downloads in the quality you choose": "اپنی پسند کی کوالٹی میں لامحدود ویڈیو ڈاؤن لوڈز",
  "Looking for the video…": "ویڈیو تلاش کی جا رہی ہے…",
  "Choose the quality": "کوالٹی چنیں",
  "Downloads": "ڈاؤن لوڈز",
  "Audio only": "صرف آڈیو",
  "Original": "اصل",
  "Play": "چلائیں",
  "Waiting for the internet…": "انٹرنیٹ کا انتظار…",
  "Only download videos you have the right to keep.": "صرف وہی ویڈیوز ڈاؤن لوڈ کریں جنہیں رکھنے کا آپ کو حق ہے۔",
  "The clipboard is empty — copy the video's link first": "کلپ بورڈ خالی ہے — پہلے ویڈیو کا لنک کاپی کریں",
  "Long-press the box and choose Paste": "خانے کو دبا کر رکھیں اور «پیسٹ» چنیں",
  "That isn't a link. Copy the video's link (it starts with https://) and paste it here.": "یہ لنک نہیں ہے۔ ویڈیو کا لنک کاپی کریں (یہ https:// سے شروع ہوتا ہے) اور یہاں پیسٹ کریں۔",
  "{site} doesn't allow its videos to be downloaded, so Attune can't save them (Google Play removes apps that do). Links that work: direct video links, Google Drive, Dropbox, archive.org, Wikimedia Commons, and pages that show a plain video file.": "{site} اپنی ویڈیوز ڈاؤن لوڈ کرنے کی اجازت نہیں دیتا، اس لیے Attune انہیں محفوظ نہیں کر سکتا (Google Play ایسا کرنے والی ایپس ہٹا دیتا ہے)۔ جو لنکس چلتے ہیں: براہِ راست ویڈیو لنکس، Google Drive، Dropbox، archive.org، Wikimedia Commons، اور وہ صفحات جن پر سادہ ویڈیو فائل ہو۔",
  "a streaming service": "اسٹریمنگ سروس",
  "this site": "یہ سائٹ",
  "That's a live-stream link (.m3u8) — it's streamed in pieces and can't be saved as one file.": "یہ لائیو اسٹریم لنک (.m3u8) ہے — یہ ٹکڑوں میں چلتا ہے اور ایک فائل کے طور پر محفوظ نہیں ہو سکتا۔",
  "Downloading works in the Android app.": "ڈاؤن لوڈ Android ایپ میں ہوتا ہے۔",
  "Google Drive didn't give the file — make sure it's shared as \"Anyone with the link\".": "Google Drive نے فائل نہیں دی — یقینی بنائیں کہ یہ \"Anyone with the link\" (لنک والا کوئی بھی) کے لیے شیئر ہے۔",
  "This page plays a {site} video, which can't be downloaded.": "یہ صفحہ {site} کی ویڈیو چلاتا ہے، جو ڈاؤن لوڈ نہیں ہو سکتی۔",
  "This page streams its video in pieces (HLS), which can't be saved as one file.": "یہ صفحہ اپنی ویڈیو ٹکڑوں میں (HLS) چلاتا ہے، جو ایک فائل کے طور پر محفوظ نہیں ہو سکتی۔",
  "No downloadable video was found on that page.": "اس صفحے پر ڈاؤن لوڈ کے قابل کوئی ویڈیو نہیں ملی۔",
  "That link didn't give a video file (the site sent {t}).": "اس لنک سے ویڈیو فائل نہیں ملی (سائٹ نے {t} بھیجا)۔",
  "No downloadable video was found there.": "وہاں ڈاؤن لوڈ کے قابل کوئی ویڈیو نہیں ملی۔",
  "Free includes 3 video downloads a day — Pro is unlimited": "مفت میں روزانہ 3 ویڈیو ڈاؤن لوڈز — Pro میں لامحدود",
  "Downloading — you can close Attune, it keeps going": "ڈاؤن لوڈ ہو رہا ہے — آپ Attune بند کر سکتے ہیں، یہ جاری رہے گا",
  "The file was moved or deleted": "فائل منتقل یا حذف ہو گئی",
