  "Reminders may come up to 10 minutes late. Tap to allow “Alarms & reminders” for Attune so they ring on the minute.": "یاد دہانیاں 10 منٹ تک دیر سے آ سکتی ہیں۔ Attune کے لیے «الارم اور یاد دہانیاں» کی اجازت دینے کے لیے ٹیپ کریں تاکہ وہ عین وقت پر بجیں۔",
  "In the browser reminders are only listed — the Android app rings them.": "براؤزر میں یاد دہانیاں صرف فہرست میں نظر آتی ہیں — Android ایپ انہیں بجاتی ہے۔",
