  "This version of Attune has no graphics-chip picture engine, so pictures are drawn on the CPU (slower). An update adds it.": "Attune کے اس ورژن میں گرافکس چپ کا تصویری انجن نہیں ہے، اس لیے تصاویر CPU پر بنتی ہیں (سست)۔ اپ ڈیٹ اسے شامل کرتی ہے۔",
